// Block (composition) — a ready-to-use sign-up form assembled from Components.
// Contract: docs/rules/block-contract.md. Arranges only (Stack for layout);
// composes Form/TextField/Checkbox/Button/Alert. Owns no Component look; mints no tokens.
import type { FormEvent, Ref } from "react";
import { Form } from "../components/Form";
import { TextField } from "../components/TextField";
import { Checkbox } from "../components/Checkbox";
import { Button } from "../components/Button";
import { Alert } from "../components/Alert";
import { Stack } from "../layouts/Stack";
import "./SignupForm.css";

export interface SignupFormProps {
  /** Heading shown above the fields. */
  heading?: string;
  /** Called with the entered account details on submit. */
  onSubmit?: (values: { name: string; email: string; password: string }) => void;
  /** Form-level error, shown above the fields. */
  errorMessage?: string;
  /** Puts the submit button in a pending state and blocks re-submit. */
  isPending?: boolean;
  className?: string;
  ref?: Ref<HTMLFormElement>;
}

export function SignupForm({
  heading = "Create account",
  onSubmit,
  errorMessage,
  isPending,
  className,
  ref,
}: SignupFormProps) {
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    onSubmit?.({
      name: String(data.get("name") ?? ""),
      email: String(data.get("email") ?? ""),
      password: String(data.get("password") ?? ""),
    });
  };

  return (
    <Form isPending={isPending}
      ref={ref}
      onSubmit={handleSubmit}
      className={className ? `sd-signupform ${className}` : "sd-signupform"}
    >
      <Stack gap="large" className="sd-signupform__content">
        {heading && (
          <>
            <h1 className="sd-signupform__heading sd-type-headline-medium">{heading}</h1>
          </>
        )}
        {/* live="assertive": see `AlertProps.live` — submit failure is the case that earns it. */}
        {errorMessage && (
          <Alert variant="error" live="assertive">
            {errorMessage}
          </Alert>
        )}
        <Stack gap="medium" className="sd-signupform__fields">
          <TextField label="Name" name="name" autoComplete="name" isRequired />
          <TextField label="Email" name="email" type="email" autoComplete="email" isRequired />
          <TextField
            label="Password"
            name="password"
            type="password"
            autoComplete="new-password"
            isRequired
          />
          {/* The box sits on the fields' box line (component-contract.md §6 rule 8). */}
          <Checkbox name="terms" isRequired>
            I agree to the terms
          </Checkbox>
        </Stack>
        <Button size="large" type="submit" variant="primary" isPending={isPending}>
          Create account
        </Button>
      </Stack>
    </Form>
  );
}

/* SignupForm.css — .sd-signupform (Block)
   Arrangement only: fills the column it is given; the page sets that column on the grid
   (a Container span or a LayoutGrid item), never this Block.
   Component look is owned by Form/TextField/Checkbox/Button/Alert; grouping is via Stack.
   No new tokens. */
.sd-signupform {
  width: 100%;
}

.sd-signupform__heading {
  margin: 0;
}
